CREATE TABLE `User` (`id` INTEGER NOT NULL AUTO_INCREMENT,`name` VARCHAR(191) NOT NULL,`email` VARCHAR(191) NOT NULL,`passwordHash` VARCHAR(191) NOT NULL,`role` ENUM('ADMIN','KARYAWAN') NOT NULL DEFAULT 'KARYAWAN',`isActive` BOOLEAN NOT NULL DEFAULT true,`isEmailVerified` BOOLEAN NOT NULL DEFAULT false,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,UNIQUE INDEX `User_email_key`(`email`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `OtpChallenge` (`id` INTEGER NOT NULL AUTO_INCREMENT,`codeHash` VARCHAR(191) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`consumedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`userId` INTEGER NOT NULL,INDEX `OtpChallenge_userId_expiresAt_idx`(`userId`,`expiresAt`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PasswordResetToken` (`id` INTEGER NOT NULL AUTO_INCREMENT,`tokenHash` VARCHAR(191) NOT NULL,`expiresAt` DATETIME(3) NOT NULL,`consumedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`userId` INTEGER NOT NULL,UNIQUE INDEX `PasswordResetToken_tokenHash_key`(`tokenHash`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Publication` (`id` INTEGER NOT NULL AUTO_INCREMENT,`title` VARCHAR(191) NOT NULL,`summary` TEXT NOT NULL,`content` LONGTEXT NOT NULL,`imageUrl` VARCHAR(191) NULL,`status` ENUM('DRAFT','PUBLISHED','ARCHIVED') NOT NULL DEFAULT 'DRAFT',`publishedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,`createdById` INTEGER NOT NULL,PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `PublicationProgress` (`id` INTEGER NOT NULL AUTO_INCREMENT,`readAt` DATETIME(3) NULL,`understoodAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updatedAt` DATETIME(3) NOT NULL,`userId` INTEGER NOT NULL,`publicationId` INTEGER NOT NULL,UNIQUE INDEX `PublicationProgress_userId_publicationId_key`(`userId`,`publicationId`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `OtpChallenge` ADD CONSTRAINT `OtpChallenge_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `PasswordResetToken` ADD CONSTRAINT `PasswordResetToken_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Publication` ADD CONSTRAINT `Publication_createdById_fkey` FOREIGN KEY (`createdById`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `PublicationProgress` ADD CONSTRAINT `PublicationProgress_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `PublicationProgress` ADD CONSTRAINT `PublicationProgress_publicationId_fkey` FOREIGN KEY (`publicationId`) REFERENCES `Publication`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
